/// <reference types="../../../types/react-table-config" />

import { Context, createContext, useContext } from 'react';
import type { Cell, ColumnInstance, Row, TableDispatch } from 'react-table';

export type TableUserActionsContextProps = {
  cell?: Cell;
  row?: Row;
  column: ColumnInstance;
  dispatch: TableDispatch;
};

export const TableUserActionsContext: Context<TableUserActionsContextProps | null> =
  createContext<TableUserActionsContextProps | null>(null);

export function useTableUserActionsContext() {
  return useContext(TableUserActionsContext);
}
